struct timespec tp;
int status;

// Retrieve system-wide real time
status = clock_gettime(CLOCK_REALTIME, &tp);

// Monotonic clock (guaranteed non-decreasing)
clock_gettime(CLOCK_MONOTONIC, &tp);

// Access retrieved time
if (status == 0) {
    time_t sec = tp.tv_sec;       // Seconds
    long nsec = tp.tv_nsec;       // Nanoseconds
}

